import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, MeshBasicMaterial, Color } = THREE;

  const root = new Group();
  root.name = config.id || 'journal-thumbnail-card';

  const cardWidth = 2.65;
  const imageHeight = 1.66;
  const captionHeight = 0.34;
  const totalHeight = imageHeight + captionHeight;
  const depth = 0.08;

  const timelines = [];
  const disposables = [];
  const primitiveCleanups = [];

  const addDisposable = (resource) => {
    if (resource) disposables.push(resource);
    return resource;
  };

  const imageGeometry = addDisposable(new PlaneGeometry(cardWidth, imageHeight));
  const imageMaterial = addDisposable(new MeshBasicNodeMaterial({
    color: new Color('#16161d'),
    toneMapped: false
  }));

  const image = new Mesh(imageGeometry, imageMaterial);
  image.name = 'journal-thumbnail-image';
  image.position.set(0, captionHeight * 0.5, 0);
  root.add(image);

  const captionGeometry = addDisposable(new BoxGeometry(cardWidth, captionHeight, depth));
  const captionMaterial = addDisposable(new MeshBasicMaterial({
    color: '#0b0b10',
    roughness: 0.72,
    metalness: 0.18
  }));

  const captionStrip = new Mesh(captionGeometry, captionMaterial);
  captionStrip.name = 'journal-caption-strip';
  captionStrip.position.set(0, -imageHeight * 0.5, 0.045);
  root.add(captionStrip);

  const frameGeometry = addDisposable(new BoxGeometry(cardWidth + 0.045, totalHeight + 0.045, 0.035));
  const frameMaterial = addDisposable(new MeshBasicMaterial({
    color: '#16161d',
    roughness: 0.62,
    metalness: 0.42
  }));

  const frame = new Mesh(frameGeometry, frameMaterial);
  frame.name = 'journal-card-frame';
  frame.position.z = -0.025;
  root.add(frame);

  const accentGeometry = addDisposable(new BoxGeometry(0.035, totalHeight + 0.1, 0.045));
  const accentMaterial = addDisposable(new MeshBasicMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0,
    depthWrite: false
  }));

  const accentEdge = new Mesh(accentGeometry, accentMaterial);
  accentEdge.name = 'journal-focus-accent';
  accentEdge.position.set(-cardWidth * 0.5 - 0.035, 0, 0.08);
  root.add(accentEdge);

  const markerGeometry = addDisposable(new BoxGeometry(0.22, 0.025, 0.05));
  const markerMaterial = addDisposable(new MeshBasicMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.9
  }));

  const marker = new Mesh(markerGeometry, markerMaterial);
  marker.name = 'journal-caption-accent';
  marker.position.set(-cardWidth * 0.5 + 0.16, -imageHeight * 0.5, 0.09);
  root.add(marker);

  const shadowGeometry = addDisposable(new PlaneGeometry(cardWidth * 1.08, 0.42));
  const shadowMaterial = addDisposable(new MeshBasicMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.46,
    depthWrite: false
  }));

  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.name = 'journal-card-contact-shadow';
  contactShadow.position.set(0.08, -totalHeight * 0.58, -0.08);
  contactShadow.scale.y = 0.42;
  root.add(contactShadow);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (!texture || root.userData.cleaned) return;
      texture.colorSpace = THREE.SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      root.userData.loadedTexture = texture;
    });
  }

  const baseY = root.position.y;
  const baseScale = root.scale.clone();

  const riseIn = () => {
    const timeline = gsap.timeline();
    timeline.to(root.position, {
      y: baseY + 0.15,
      duration: 0.32,
      ease: 'power3.out'
    });
    timeline.to(root.rotation, {
      x: -0.025,
      z: 0.018,
      duration: 0.3,
      ease: 'power2.out'
    }, '<');
    timelines.push(timeline);
  };

  const settle = () => {
    const timeline = gsap.timeline();
    timeline.to(root.position, {
      y: baseY,
      duration: 0.42,
      ease: 'power3.out'
    });
    timeline.to(root.rotation, {
      x: 0,
      z: 0,
      duration: 0.34,
      ease: 'power2.out'
    }, '<');
    timelines.push(timeline);
  };

  const press = () => {
    const timeline = gsap.timeline();
    timeline.to(root.scale, {
      x: baseScale.x * 0.97,
      y: baseScale.y * 0.97,
      z: baseScale.z * 0.97,
      duration: 0.12,
      ease: 'power2.out'
    });
    timeline.to(root.scale, {
      x: baseScale.x,
      y: baseScale.y,
      z: baseScale.z,
      duration: 0.34,
      ease: 'back.out(2.2)'
    });
    timelines.push(timeline);
  };

  const focus = (active = true) => {
    const timeline = gsap.to(accentMaterial, {
      opacity: active ? 1 : 0,
      duration: 0.2,
      ease: 'power2.out'
    });
    timelines.push(timeline);
  };

  root.userData.handlers = {
    hover: (active = true) => {
      if (active) riseIn();
      else settle();
    },
    pointerover: riseIn,
    pointerout: settle,
    focus,
    blur: () => focus(false),
    click: () => {
      press();
      if (ctx.emit) ctx.emit('hub-journal.select', {
        node: root.name,
        source: 'journal-thumbnail-card'
      });
    }
  };

  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const cleanup of primitiveCleanups) {
      if (cleanup) cleanup();
    }

    for (const resource of disposables) {
      if (resource?.dispose) resource.dispose();
    }

    root.clear();
  };

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const runner = ctx.primitives?.[primitive.name]?.(root, primitive.params);
    if (runner?.cleanup) primitiveCleanups.push(() => runner.cleanup());
    if (runner?.timeline) timelines.push(runner.timeline);
  }

  return root;
}
